// Keep the public manifest and first-paint randomizer in sync with the files.
// Automatically regenerated by npm prebuild/predev when photos change.
import { readdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const folder = resolve(root, 'public/login-backgrounds');
const entries = await readdir(folder, { withFileTypes: true });
const photos = entries
  .filter(entry => entry.isFile() && /\.(png|jpe?g|webp|avif)$/i.test(entry.name))
  .map(entry => entry.name)
  .sort((a, b) => a.localeCompare(b, 'vi', { numeric: true }));
const urls = photos.map(name => '/login-backgrounds/' + encodeURIComponent(name));
const manifest = {
  version: 1,
  title: 'QL Ảnh — login background collection',
  description: 'Auto-rotating login backgrounds; regenerated from the images in this directory during build.',
  images: photos.map((name, i) => ({ src: urls[i], alt: name.replace(/\.[^.]+$/, '') }))
};
await writeFile(resolve(folder, 'backgrounds.json'), JSON.stringify(manifest, null, 2) + '\n', 'utf8');
const boot = `// Auto-generated by scripts/generate-login-backgrounds.mjs. Do not edit.
(() => {
  'use strict';
  const images = ${JSON.stringify(urls)};
  function randomOrder(values) {
    for (let i = values.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [values[i], values[j]] = [values[j], values[i]];
    }
    return values;
  }
  const order = randomOrder(images.slice());
  try {
    const last = sessionStorage.getItem('vl-login-previous-opening-photo');
    if (order.length > 1 && order[0] === last) {
      const position = 1 + Math.floor(Math.random() * (order.length - 1));
      [order[0], order[position]] = [order[position], order[0]];
    }
    if (order[0]) sessionStorage.setItem('vl-login-previous-opening-photo', order[0]);
  } catch (_) {}
  const initial = order[0] || null;
  window.__vlLoginBackgroundBoot = {images, order, initial};
  if (initial) document.documentElement.style.setProperty('--vl-login-first-photo', 'url(' + JSON.stringify(initial) + ')');
})();
`;
await writeFile(resolve(folder, 'bootstrap.js'), boot, 'utf8');
console.log('[login backgrounds] ' + photos.length + ' image(s) registered; random first-paint bootstrap generated.');
